// 自定义评分脚本
// score: 总分
// answers: 用户答案数组
// questions: 题目数组

function calculateResult(score, answers, questions) {
  // 在这里编写你的评分逻辑
  if (score >= 80) {
    return {
      level: 'high',
      result: '优秀',
      description: '您的心理健康状况良好'
    };
  } else if (score >= 60) {
    return {
      level: 'medium',
      result: '良好',
      description: '您的心理健康状况正常'
    };
  } else {
    return {
      level: 'low',
      result: '需要关注',
      description: '建议寻求专业帮助'
    };
  }
}
